function campaignOn(){return !!(game&&game.campaign&&game.campaign.chapters)}function saveKey(){return campaignOn()&&campaign?`${STORE}-${game.metadata.id}-${campaign.run[campaign.index]}`:`${STORE}-${game.metadata.id}`}function writeCampaign(){if(campaignOn()&&campaign)localStorage.setItem(`${CAMPAIGN}-${game.campaign.id}`,JSON.stringify(campaign))}function startCampaign(){const pool=[...game.campaign.lieutenant_pool],run=[],n=game.campaign.lieutenant_chapters||2;while(run.length<n&&pool.length){const i=Math.floor(Math.random()*pool.length);run.push(pool.splice(i,1)[0])}run.push(game.campaign.boss);campaign={run,index:0};writeCampaign();return campaign}function readCampaign(){try{const raw=JSON.parse(localStorage.getItem(`${CAMPAIGN}-${game.campaign.id}`)||"null");if(Array.isArray(raw?.run)&&raw.run.length){campaign=raw;return campaign}}catch{}return startCampaign()}function applyChapter(){if(!campaignOn()||!campaign)return;const ch=game.campaign.chapters[campaign.run[campaign.index]];if(!ch)return;game.culprit=ch.culprit;if(ch.start)game.metadata.start=ch.start;if(ch.briefing)game.metadata.briefing=ch.briefing;if(ch.total_hours)game.metadata.total_hours=ch.total_hours;if(ch.arrest_requirements)game.arrest_requirements=ch.arrest_requirements;if(ch.scenarios)game.scenarios=ch.scenarios}
