function clock(){el.time.textContent=`${Math.max(0,state.hours)}h`;el.timeBar.style.width=`${Math.max(0,state.hours)/game.metadata.total_hours*100}%`;el.time.closest(".location-header").classList.toggle("danger",state.hours<=16)}
function map(){const active=scenario(),navigation=active?.navigation||game.navigation,allowed=new Set(navigation[state.location]||[]),visible=[];for(const city of game.locations)if(city.id===state.location||state.visited.includes(city.id)||allowed.has(city.id))visible.push(city);el.cities.innerHTML=visible.map(c=>{const current=c.id===state.location,visited=state.visited.includes(c.id),canGo=allowed.has(c.id),cost=canGo?game.travel[state.location][c.id]:0;return`<button class="city ${current?"current":visited?"visited":""}" style="left:${c.x}%;top:${c.y}%" data-city="${c.id}" ${current||!canGo||state.finished?"disabled":""} aria-label="${current?c.name+", posição atual":"Viajar para "+c.name+", "+cost+" horas"}"><span class="city-pulse"></span><span class="city-name">${c.name}</span><small>${current?"POSIÇÃO ATUAL":visited&&!canGo?"VISITADA":cost+"h"}</small></button>`}).join("");el.cities.querySelectorAll(".city:not(:disabled)").forEach(b=>b.onclick=()=>openTravel(b.dataset.city));const pts=state.route.map(id=>loc(id)).map(c=>`${c.x*10},${c.y*6.2}`).join(" ");el.lines.innerHTML=`<polyline points="${pts}" fill="none" stroke="#d6ff54" stroke-width="2" stroke-dasharray="7 8" vector-effect="non-scaling-stroke"/>`}
